function defaults(){
 const workflows=Object.fromEntries(TYPES.map(t=>[t,defaultFlow()])),forms=Object.fromEntries(TYPES.map(t=>[t,defaultForm()]));
 const permissions={admin:Object.fromEntries(PERMISSIONS.map(p=>[p,true])),requester:{view:true,create:true,export:false,review:false,approve:false,configure:false},facilities:{view:true,create:false,review:true,approve:false,export:true,configure:false},manager:{view:true,create:true,review:true,approve:false,export:true,configure:false},approver:{view:true,create:false,review:true,approve:true,export:true,configure:false},limited:{view:true,create:false,review:false,approve:false,export:false,configure:false}};
 const makeRequest=(id,type,sites,org,start,end,reason,stage=0)=>({id,type,sites,org,subject:type+' — '+siteName(sites[0]),start:dubaiISO(start),end:dubaiISO(end),permanent:false,unit:'days',reason,values:{reason},files:[],status:'submitted',stage,done:[],flow:clone(workflows[type]),form:clone(forms[type]),history:[{event:'تقديم الطلب',actor:'مقدم طلب تجريبي',at:'2026-10-28T04:00:00Z'}],createdAt:'2026-10-28T04:00:00Z',createdRole:'requester',revision:1,cc:['الإدارة العامة'],bookingRef:null});
 return {schema:2,role:'admin',workflows,forms,permissions,scopes:{admin:'all',requester:'organization',facilities:'all',manager:'organization',approver:'all',limited:'site'},settings:{multiSites:true,multiOrgs:true,signatureRequired:true,showOccupant:true,defaultUnit:'days',timezone:'Asia/Dubai',allowSelfApproval:false},requests:[makeRequest('MV-2026-0184','إشغال مؤقت',['s2'],'الخدمات المشتركة','2026-11-02','2026-11-04','استخدام المرفق لاستقبال الموظفين خلال البرنامج الإداري.',1),makeRequest('MV-2026-0185','إشغال مؤقت',['s4'],'الإدارة العامة','2026-11-05','2026-11-06','تنظيم اجتماع إداري خلال الفترة المطلوبة.')],bookings:[{id:'BK-001',site:'s1',org:'الإدارة العامة',start:dubaiISO('2026-11-01'),end:dubaiISO('2026-12-01'),status:'confirmed',requestId:'DEMO-101'},{id:'BK-002',site:'s3',org:'إدارة المشاريع',start:dubaiISO('2026-11-01'),end:dubaiISO('2026-11-05'),status:'confirmed',requestId:'DEMO-102'},{id:'BK-003',site:'s6',org:'إدارة التقنية',start:dubaiISO('2026-11-01'),end:dubaiISO('2026-11-04'),status:'confirmed',requestId:'DEMO-103'}],audit:[{id:1,event:'تهيئة بيانات العرض',actor:'النظام التجريبي',at:'2026-10-28T04:00:00Z',detail:'مرافق وجهات وطلبات افتراضية'}]};
}
let state;try{const v=JSON.parse(localStorage.getItem(STORE_KEY));state=v?.schema===2?v:defaults()}catch(e){state=defaults()}
let view='map',selectedSite='s2',selectedRequest=state.requests[0]?.id,map=null,mapMarkers=null,mapBounds=null,mapToken=0,decodedMap=null,toastTimer,orgFilter='all',siteQuery='',statusFilter='all',requestQuery='',requestStatus='all',calendarDay=0,mapMode='availability',mapDate='2026-11-01',flowType='إشغال مؤقت',formType='إشغال مؤقت',flowDraft=null,formDraft=null,permissionRole='requester',orgSelected='all',wizard=null,wizardStep=1,draggedStage=null;
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));return true}catch(e){toast('التخزين المحلي غير متاح. صدّر نسخة من التجربة.');return false}}
function audit(event,detail=''){state.audit.unshift({id:Date.now()+Math.random(),event,detail,actor:ROLE_NAMES[state.role],at:new Date().toISOString()});state.audit=state.audit.slice(0,300);persist()}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),700)}
function can(action){return !!state.permissions[state.role]?.[action]}
function limited(){return state.role==='limited'}
function scopeAllows(org,site){let s=state.scopes[state.role]||'all';if(s==='all')return true;if(s==='organization')return org==='الخدمات المشتركة';if(s==='site')return ['s2','s5','s8'].includes(site);return org==='الخدمات المشتركة'&&['s2','s5','s8'].includes(site)}
function visibleSites(){return SITES.filter(s=>scopeAllows(s.org,s.id)&&(orgFilter==='all'||s.org===orgFilter)&&(!siteQuery||(s.name+' '+s.org).includes(siteQuery))&&(statusFilter==='all'||availability(s.id).key===statusFilter))}
function visibleRequests(){if(limited())return [];return state.requests.filter(r=>r.sites.some(id=>scopeAllows(r.org,id))&&(state.role!=='requester'||r.createdRole==='requester'))}
function overlaps(a,b,c,d){return new Date(a).getTime()<(d?new Date(d).getTime():Infinity)&&new Date(c).getTime()<(b?new Date(b).getTime():Infinity)}
function dateRange(date=mapDate){let d=new Date(dubaiISO(date)),e=new Date(d.getTime()+86400000);return [d.toISOString(),e.toISOString()]}
function availability(site,date=mapDate){const [a,b]=dateRange(date);const bookings=state.bookings.filter(x=>x.site===site&&x.status==='confirmed'&&overlaps(a,b,x.start,x.end));const pending=state.requests.filter(r=>r.status==='submitted'&&r.sites.includes(site)&&!['إلغاء','إخلاء'].includes(r.type)&&overlaps(a,b,r.start,r.end));return bookings.length?{key:'busy',label:'محجوز',color:'#c77770',booking:bookings[0],pending}:pending.length?{key:'pending',label:'طلب قيد المراجعة',color:'#d4a04d',pending}:{key:'free',label:'متاح',color:'#439b7e',pending:[]}}
function administrativeColor(id){let a=availability(id);return a.key==='busy'?{...a,color:'#439b7e',label:'حجز معتمد'}:a.key==='pending'?a:{...a,color:'#9daea3',label:'دون طلب قائم'}}
function heading(en,title,description,actions=''){return '<div class="page-heading"><div><span class="eyebrow">'+en+'</span><h1>'+title+'</h1><p>'+description+'</p></div><div class="heading-actions">'+actions+'</div></div>'}
function stat(value,label,ico){return '<div class="card stat-card"><div><b>'+value+'</b><span>'+label+'</span></div><i class="stat-icon">'+icon(ico)+'</i></div>'}
function toggleNavigation(){const open=document.body.classList.toggle('nav-open');$('#navShade').hidden=!open}
function changeRole(role){state.role=role;persist();$('#roleAvatar').textContent=ROLE_SHORT[role];orgFilter='all';siteQuery='';toast('محاكاة واجهة دور: '+ROLE_NAMES[role]);render()}
function navigation(){const pending=visibleRequests().filter(r=>r.status==='submitted').length;$('#navigation').innerHTML=NAV.map(([id,ico,label],i)=>(i===5?'<div class="nav-divider"></div>':'')+'<a class="nav-item '+(view===id?'active':'')+'" href="#'+id+'">'+icon(ico)+'<span>'+label+'</span>'+(['review','requests'].includes(id)?'<span class="nav-count">'+pending+'</span>':'')+'</a>').join('');$('#breadcrumbTitle').textContent=NAV.find(x=>x[0]===view)?.[2]||'مساحة العمل';$('#demoRole').value=state.role;$('#roleAvatar').textContent=ROLE_SHORT[state.role]}
function route(){const next=location.hash.replace('#','')||'map';view=NAV.some(x=>x[0]===next)?next:'map';document.body.classList.remove('nav-open');$('#navShade').hidden=true;render();window.scrollTo({top:0,behavior:'instant'})}
function noAccess(){return '<section class="card permission-denied">'+icon('shield')+'<h2>هذا القسم خارج صلاحية الدور المعروض</h2><p>غيّر «تجربة الدور» لمعاينة واجهة أخرى. هذا التحكم توضيحي في النموذج.</p><a class="button primary" href="#map">العودة إلى الخريطة</a></section>'}
function render(){if(map){map.remove();map=null}mapToken++;navigation();const restricted=(limited()&&!['map','calendar','handoff'].includes(view))||(ADMIN_VIEWS.includes(view)&&!can('configure'))||(view==='review'&&!can('review'))||(!can('view')&&view!=='handoff');if(restricted){$('#main').innerHTML=noAccess();return}const renderers={map:renderMapView,requests:renderRequests,review:renderReview,calendar:renderCalendar,org:renderOrg,workflow:renderWorkflow,forms:renderForms,permissions:renderPermissions,settings:renderSettings,audit:renderAudit,handoff:renderHandoff};$('#main').innerHTML=renderers[view]();if($('#map'))createMap();if(view==='map')renderSiteList();if(view==='forms')renderFormPreview();requestAnimationFrame(()=>{if(map)map.invalidateSize({pan:false})})}
function mapBox(cls=''){return '<section class="card map-card '+cls+'"><div id="map" class="map" aria-label="خريطة مرافق افتراضية"></div><div class="map-toolbar"><div class="map-mode"><button class="'+(mapMode==='availability'?'active':'')+'" onclick="setMapMode(\'availability\')">إتاحة المرافق</button><button class="'+(mapMode==='administrative'?'active':'')+'" onclick="setMapMode(\'administrative\')">حالة الطلبات</button></div><div class="map-tools"><button class="icon-button" onclick="map.zoomIn()" aria-label="تكبير الخريطة">＋</button><button class="icon-button" onclick="map.zoomOut()" aria-label="تصغير الخريطة">−</button><button class="icon-button" onclick="fitMap()" aria-label="عرض المرافق">'+icon('pin')+'</button><button class="icon-button" onclick="toggleMapLabels()" aria-label="إظهار أسماء المرافق">'+icon('layers')+'</button></div></div><div class="map-legend" id="mapLegend">'+mapLegend()+'</div><div class="map-caption" id="mapCaption">خريطة جغرافية مضمّنة · مواقع وحدود افتراضية</div></section>'}
function mapLegend(){return mapMode==='availability'?'<span><i class="dot" style="color:#439b7e"></i>متاح</span><span><i class="dot" style="color:#d4a04d"></i>طلب معلّق</span><span><i class="dot" style="color:#c77770"></i>محجوز</span>':'<span><i class="dot" style="color:#439b7e"></i>حجز معتمد</span><span><i class="dot" style="color:#d4a04d"></i>طلب معلّق</span><span><i class="dot" style="color:#9daea3"></i>دون طلب</span>'}
let showMapLabels=true;
async function createMap(){const token=mapToken;map=L.map('map',{zoomControl:false,attributionControl:true,minZoom:10.5,maxZoom:17,zoomSnap:.5}).setView([25.207,55.31],12);const thisMap=map;thisMap.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet</a>');thisMap.createPane('baseImage');thisMap.getPane('baseImage').style.zIndex='150';mapMarkers=L.layerGroup().addTo(thisMap);mapBounds=L.layerGroup().addTo(thisMap);drawMap();fitMap();try{if(!decodedMap){const bytes=Uint8Array.from(atob(EMBEDDED_MAP),c=>c.charCodeAt(0));decodedMap=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text()}if(token!==mapToken||thisMap!==map)return;L.imageOverlay('data:image/svg+xml;base64,'+btoa(decodedMap),[[25.07,55.19],[25.33,55.46]],{pane:'baseImage',interactive:false}).addTo(thisMap);thisMap.attributionControl.addAttribution('<a href="https://openfreemap.org" target="_blank" rel="noopener">OpenFreeMap</a> © <a href="https://openmaptiles.org" target="_blank" rel="noopener">OpenMapTiles</a> Data from <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>');$('#mapCaption').textContent='خريطة جغرافية مضمّنة · المرافق والحدود افتراضية'}catch(e){if(token===mapToken&&$('#mapCaption'))$('#mapCaption').textContent='تتطلب الخلفية متصفحاً حديثاً · علامات المرافق متاحة'}requestAnimationFrame(()=>{if(token===mapToken&&map){map.invalidateSize({pan:false});fitMap()}})}
function mapSites(){if(view==='review'){const r=state.requests.find(x=>x.id===selectedRequest);return SITES.filter(s=>r?.sites.includes(s.id)&&scopeAllows(r.org,s.id))}return visibleSites()}
function fitMap(){const list=mapSites();if(map&&list.length)map.fitBounds(list.map(s=>[s.lat,s.lng]),{paddingTopLeft:[45,85],paddingBottomRight:[45,85],maxZoom:list.length===1?13.5:13,animate:false})}
function drawMap(){if(!mapMarkers)return;mapMarkers.clearLayers();mapBounds.clearLayers();mapSites().forEach(s=>{const a=mapMode==='availability'?availability(s.id):administrativeColor(s.id);const selected=s.id===selectedSite;L.polygon([[s.lat-.001,s.lng-.0013],[s.lat-.0008,s.lng+.0016],[s.lat+.0011,s.lng+.001],[s.lat+.001,s.lng-.0013]],{color:a.color,weight:selected?2:1,fillColor:a.color,fillOpacity:.16}).addTo(mapBounds).on('click',()=>selectSite(s.id));const html='<div class="pin-wrap '+(selected?'selected':'')+'" style="--pin:'+a.color+'"><span class="pin-head"><i>'+s.code+'</i></span>'+(showMapLabels?'<span class="pin-label">'+s.name+'</span>':'')+'</div>';L.marker([s.lat,s.lng],{title:s.name+' — '+a.label,zIndexOffset:selected?1000:0,icon:L.divIcon({className:'pin-icon',html,iconSize:[0,0],iconAnchor:[0,0]})}).addTo(mapMarkers).on('click',()=>selectSite(s.id))})}
function setMapMode(mode){mapMode=mode;$$('.map-mode button').forEach((b,i)=>b.classList.toggle('active',i===(mode==='availability'?0:1)));if($('#mapLegend'))$('#mapLegend').innerHTML=mapLegend();drawMap()}
function toggleMapLabels(){showMapLabels=!showMapLabels;drawMap()}
function setMapDate(date){if(!date)return;mapDate=date;drawMap();if(view==='map'){renderSiteList();$('#mapStats').innerHTML=mapStats()}if(view==='calendar')render()}
function setMapFilter(key,value){if(key==='org')orgFilter=value;if(key==='status')statusFilter=value;if(key==='query')siteQuery=value;const list=visibleSites();if(list.length&&!list.some(s=>s.id===selectedSite))selectedSite=list[0].id;drawMap();renderSiteList();$('#mapStats').innerHTML=mapStats()}
function selectSite(id){selectedSite=id;drawMap();if(view==='map')renderSiteList();if(view==='calendar')render();if(view==='review')toast(siteName(id)+' · مرفق وارد في الطلب')}
function mapStats(){const list=visibleSites();return stat(list.length,'مرافق في نطاق العرض','building')+stat(list.filter(s=>availability(s.id).key==='free').length,'متاحة في اليوم المختار','pin')+stat(visibleRequests().filter(r=>r.status==='submitted').length,'طلبات قيد المراجعة','file')+stat(state.bookings.filter(b=>b.status==='confirmed'&&list.some(s=>s.id===b.site)).length,'حجوزات معتمدة','check')}
function renderMapView(){return heading('FACILITIES / MAP WORKSPACE','المكان، والطلب، في سياق واحد','اختر المرفق من الخريطة، واستعرض إتاحته أو ابدأ طلباً إدارياً عليه.','<span class="pill green"><i class="dot"></i>نسخة تجريبية مستقلة</span>')+'<div class="stats" id="mapStats">'+mapStats()+'</div><div class="card filterbar"><label>الجهة<select onchange="setMapFilter(\'org\',this.value)"><option value="all">جميع الجهات</option>'+ORGS.map(o=>'<option '+(orgFilter===o?'selected':'')+'>'+o+'</option>').join('')+'</select></label><label>اليوم<input type="date" value="'+mapDate+'" onchange="setMapDate(this.value)" aria-label="تاريخ الخريطة"></label><label>الإتاحة<select onchange="setMapFilter(\'status\',this.value)"><option value="all">الكل</option>'+[['free','متاح'],['pending','طلب معلّق'],['busy','محجوز']].map(([id,n])=>'<option value="'+id+'" '+(statusFilter===id?'selected':'')+'>'+n+'</option>').join('')+'</select></label><span class="grow"></span><span class="micro muted">الموقع دائم · الحجوزات مرتبطة بفترات</span></div><div class="workspace">'+mapBox()+'<aside class="card site-aside"><div class="flex spread"><h3>دليل المرافق</h3><span class="pill" id="siteCount"></span></div><div class="search-box">'+icon('search')+'<input placeholder="ابحث عن مرفق…" aria-label="البحث في المرافق" value="'+esc(siteQuery)+'" oninput="setMapFilter(\'query\',this.value)"></div><div class="site-list" id="siteList"></div><div class="site-detail" id="siteDetail"></div></aside></div>'}
function renderSiteList(){if(!$('#siteList'))return;const list=visibleSites();$('#siteCount').textContent=list.length;$('#siteList').innerHTML=list.length?list.map(s=>{let a=availability(s.id);return '<button class="site-row '+(selectedSite===s.id?'active':'')+'" onclick="selectSite(\''+s.id+'\')"><span>'+s.code+'</span><div><b>'+s.name+'</b><small>'+(limited()?'مرفق ضمن نطاق العرض':s.org)+'</small></div><i class="dot" style="color:'+a.color+'" title="'+a.label+'"></i></button>'}).join(''):'<div class="empty">لا توجد مرافق مطابقة</div>';const s=list.find(x=>x.id===selectedSite)||list[0];if(!s){$('#siteDetail').innerHTML='<p class="micro muted">غيّر التصفية لعرض المرافق.</p>';return}selectedSite=s.id;const a=availability(s.id);$('#siteDetail').innerHTML='<div class="flex spread"><span class="eyebrow">FACILITY / '+s.code+'</span><span class="pill '+(a.key==='busy'?'red':a.key==='pending'?'orange':'green')+'">'+a.label+'</span></div><h2>'+s.name+'</h2><p class="muted micro">'+(limited()?'بيانات مختصرة':s.org)+'</p><dl class="meta-grid"><div><dt>الموقع الرئيسي</dt><dd>مجمع المؤسسة</dd></div><div><dt>التصنيف</dt><dd>'+s.kind+'</dd></div><div><dt>السعة</dt><dd>'+s.capacity+' شخصاً</dd></div><div><dt>تاريخ العرض</dt><dd>'+fullDate(dubaiISO(mapDate))+'</dd></div></dl>'+(limited()?'':'<button class="button primary full" onclick="openRequest(\''+s.id+'\')" '+(!can('create')?'disabled':'')+'>＋ طلب على هذا المرفق</button>')+'<p class="micro muted" style="margin-top:10px">البرتقالي طلب معلّق؛ الحجز النهائي يبدأ بالاعتماد.</p>'}
function requestRows(list){if(!list.length)return '<tr><td colspan="7" class="empty">لا توجد طلبات مطابقة</td></tr>';return list.map(r=>'<tr><td><button class="link-button latin" onclick="showRequest(\''+r.id+'\')">'+esc(r.id)+'</button></td><td>'+esc(r.type)+'</td><td>'+r.sites.map(siteName).join('، ')+'</td><td>'+(limited()?'مقيد':esc(r.org))+'</td><td>'+fullDate(r.start)+'<br><span class="muted micro">'+(r.end?fullDate(r.end):'دائم')+'</span></td><td>'+statusPill(r.status)+'</td><td>'+(['draft','returned'].includes(r.status)&&can('create')?'<button class="button compact" onclick="editRequest(\''+r.id+'\')">تعديل وإرسال</button>':'<button class="button compact" onclick="showRequest(\''+r.id+'\')">تفاصيل</button>')+'</td></tr>').join('')}
function renderRequests(){const list=visibleRequests().filter(r=>(requestStatus==='all'||r.status===requestStatus)&&(!requestQuery||(r.id+' '+r.subject+' '+r.org).includes(requestQuery)));return heading('REQUESTS / ADMINISTRATIVE SERVICES','الطلبات','كل طلب يحتفظ بنسخة النموذج والتدفق اللذين بدأ بهما.','<button class="button" onclick="exportRequests()" '+(!can('export')?'disabled':'')+'>'+icon('download')+'تصدير</button><button class="button primary" onclick="openRequest()" '+(!can('create')?'disabled':'')+'>＋ طلب جديد</button>')+'<div class="card"><div class="filterbar" style="margin:0;border-bottom:1px solid var(--line)"><div class="search-inline"><input placeholder="رقم الطلب أو الجهة…" value="'+esc(requestQuery)+'" aria-label="بحث الطلبات" oninput="filterRequests(this.value)"></div><label>الحالة<select onchange="requestStatus=this.value;render()"><option value="all">كل الحالات</option>'+Object.entries(STATUS).map(([k,v])=>'<option value="'+k+'" '+(requestStatus===k?'selected':'')+'>'+v[0]+'</option>').join('')+'</select></label><span class="micro muted">'+list.length+' طلب في العرض</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>رقم الطلب</th><th>النوع</th><th>المرافق</th><th>الجهة</th><th>الفترة</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody id="requestRows">'+requestRows(list)+'</tbody></table></div><div class="legend-note"><strong>ملاحظة:</strong> هذه سجلات تجريبية محفوظة داخل المتصفح.</div></div>'}
function filterRequests(q){requestQuery=q;const list=visibleRequests().filter(r=>(requestStatus==='all'||r.status===requestStatus)&&(!q||(r.id+' '+r.subject+' '+r.org).includes(q)));$('#requestRows').innerHTML=requestRows(list)}
function exportRequests(){if(!can('export'))return toast('الدور المعروض لا يملك التصدير');const rows=[['رقم الطلب','النوع','الجهة','الحالة','المرافق'],...visibleRequests().map(r=>[r.id,r.type,r.org,STATUS[r.status][0],r.sites.map(siteName).join('، ')])];download('mover-demo-requests.csv','\ufeff'+rows.map(a=>a.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv;charset=utf-8');toast('تم تصدير الطلبات التجريبية')}
function effectiveForm(){return wizard?.form||state.forms[wizard?.type||TYPES[0]]}
function openRequest(site){if(!can('create'))return toast('الدور المعروض لا يملك إنشاء الطلبات');wizard={id:null,type:'إشغال مؤقت',org:'الخدمات المشتركة',orgs:['الخدمات المشتركة'],sites:[site||selectedSite],subject:'',unit:state.settings.defaultUnit,start:'2026-11-02',end:'2026-11-04',reason:'',values:{},files:[],cc:[],bookingRef:null};wizardStep=1;renderWizard();$('#requestDialog').showModal()}
function editRequest(id){const r=state.requests.find(x=>x.id===id);if(!r||!['draft','returned'].includes(r.status)||!can('create'))return;wizard={...clone(r),start:r.unit==='hours'?localInput(r.start):(localInput(r.start)||'').slice(0,10),end:r.end?(r.unit==='hours'?localInput(r.end):localInput(r.end).slice(0,10)):'',values:{...r.values,reason:r.reason},orgs:r.orgs||[r.org]};wizardStep=1;renderWizard();$('#requestDialog').showModal()}
function closeRequest(){$('#requestDialog').close()}
function chooseRequestType(type){wizard.type=type;if(!wizard.id){delete wizard.form;delete wizard.flow}wizard.bookingRef=null;renderWizard()}
function captureWizard(){if(!wizard)return;if($('#wOrg'))wizard.org=$('#wOrg').value;if($('#wSubject'))wizard.subject=$('#wSubject').value;if($('#wStart'))wizard.start=$('#wStart').value;if($('#wEnd'))wizard.end=$('#wEnd').value;if($('#wBooking'))wizard.bookingRef=$('#wBooking').value||null;$$('[data-wfield]').forEach(el=>{wizard.values[el.dataset.wfield]=el.value;if(el.dataset.wfield==='reason')wizard.reason=el.value});wizard.cc=$$('[data-cc]:checked').map(el=>el.value);if($('#wOtherOrgs'))wizard.orgs=[wizard.org,...$('#wOtherOrgs').selectedOptions].map(x=>typeof x==='string'?x:x.value).filter((v,i,a)=>a.indexOf(v)===i)}
function selectWizardSite(id,checked){captureWizard();if(checked){wizard.sites=state.settings.multiSites?[...new Set([...wizard.sites,id])]:[id]}else wizard.sites=wizard.sites.filter(x=>x!==id);renderWizard()}
function changeWizardUnit(unit){captureWizard();wizard.unit=unit;if(unit==='hours'){wizard.start=(wizard.start||'2026-11-02').slice(0,10)+'T09:00';wizard.end=(wizard.end||'2026-11-04').slice(0,10)+'T17:00'}else {wizard.start=(wizard.start||'2026-11-02').slice(0,10);wizard.end=(wizard.end||'2026-11-04').slice(0,10)}renderWizard()}
function wizardField(f,preview=false){const v=wizard?.values?.[f.id]||'';const attrs=preview?'disabled':'data-wfield="'+f.id+'"';const star=f.required?' <span style="color:#c99758">*</span>':'';let control;if(f.kind==='textarea')control='<textarea '+attrs+' placeholder="'+esc(f.label)+'">'+esc(v)+'</textarea>';else if(f.kind==='files')control='<input type="file" multiple '+(preview?'disabled':'onchange="wizard.files=[...this.files].map(f=>({name:f.name,size:f.size}));wizard.values[\''+f.id+'\']=wizard.files.length"')+'><small>النموذج يحفظ أسماء الملفات وأحجامها فقط.</small>'+(wizard?.files?.length?'<small>'+wizard.files.map(x=>esc(x.name)).join('، ')+'</small>':'');else if(f.kind==='select')control='<select '+attrs+'><option value="">اختر…</option>'+(f.options||'أولوية عادية,أولوية مرتفعة').split(',').map(o=>'<option '+(o===v?'selected':'')+'>'+esc(o.trim())+'</option>').join('')+'</select>';else control='<input type="'+(f.kind==='number'?'number':f.kind==='date'?'date':'text')+'" '+attrs+' value="'+esc(v)+'" '+(f.kind==='number'?'min="1"':'')+'>';return '<label class="field"><span>'+esc(f.label)+star+'</span>'+control+'</label>'}
function renderWizard(){const t=wizard.type;const form=effectiveForm();let content='';if(wizardStep===1){content='<div class="wizard-title"><h3>الجهة ونوع الخدمة</h3><p>اختر الطلب الإداري الذي يحتاجه فريقك.</p></div><label class="field"><span>الجهة الطالبة</span><select id="wOrg">'+ORGS.map(o=>'<option '+(wizard.org===o?'selected':'')+'>'+o+'</option>').join('')+'</select></label>'+(state.settings.multiOrgs?'<label class="field"><span>جهات مشاركة — اختياري</span><select id="wOtherOrgs" multiple size="2">'+ORGS.filter(o=>o!==wizard.org).map(o=>'<option '+(wizard.orgs?.includes(o)?'selected':'')+'>'+o+'</option>').join('')+'</select><small>يمكن اختيار عدة جهات.</small></label>':'')+'<div class="type-grid">'+TYPES.map(type=>'<button class="type-button '+(type===t?'active':'')+'" '+(wizard.id?'disabled':'')+' onclick="captureWizard();chooseRequestType(\''+type+'\')">'+icon(type==='إشغال مؤقت'?'clock':type==='إلغاء'?'close':'building')+type+'</button>').join('')+'</div><label class="field"><span>عنوان الطلب</span><input id="wSubject" value="'+esc(wizard.subject)+'" placeholder="مثال: استخدام مركز الخدمات لاستقبال الموظفين"></label>';if(['تمديد','تعديل','إلغاء','إخلاء'].includes(t))content+='<label class="field"><span>الحجز المعتمد المرتبط</span><select id="wBooking"><option value="">اختر حجزاً قائماً…</option>'+state.bookings.filter(b=>b.status==='confirmed').map(b=>'<option value="'+b.id+'" '+(wizard.bookingRef===b.id?'selected':'')+'>'+b.id+' — '+siteName(b.site)+'</option>').join('')+'</select></label>'}
 if(wizardStep===2){content='<div class="wizard-title"><h3>المرافق والفترة</h3><p>المرفق ثابت في السجل، والحجز مرتبط بفترة مستقلة.</p></div><div class="site-pick-grid">'+SITES.filter(s=>scopeAllows(s.org,s.id)).map(s=>'<label class="site-pick"><input type="checkbox" '+(wizard.sites.includes(s.id)?'checked':'')+' onchange="selectWizardSite(\''+s.id+'\',this.checked)"><span>'+s.name+'<small>'+s.kind+'</small></span></label>').join('')+'</div><div class="selected-count">'+wizard.sites.length+' مرفق محدد · '+(state.settings.multiSites?'اختيار متعدد مفعّل':'مرفق واحد فقط')+'</div><label class="field"><span>وحدة الفترة</span><select onchange="changeWizardUnit(this.value)"><option value="days" '+(wizard.unit==='days'?'selected':'')+'>بالأيام</option><option value="hours" '+(wizard.unit==='hours'?'selected':'')+'>بالساعات</option></select></label><div class="row"><label class="field"><span>بداية الاستخدام</span><input id="wStart" type="'+(wizard.unit==='hours'?'datetime-local':'date')+'" value="'+esc(wizard.start)+'"></label><label class="field"><span>نهاية الاستخدام — غير مشمولة</span><input id="wEnd" type="'+(wizard.unit==='hours'?'datetime-local':'date')+'" value="'+esc(wizard.end)+'"></label></div><p class="micro muted">الأوقات حسب الإمارات. نهاية الفترة حد غير مشمول؛ حجز 1 إلى 4 نوفمبر ينتهي عند بداية يوم 4.</p><div class="note orange" style="margin-top:15px">الحجز النهائي لا ينشأ عند إرسال الطلب. يظهر الطلب بالبرتقالي أثناء المراجعة.</div>'}
 if(wizardStep===3){content='<div class="wizard-title"><h3>تفاصيل النموذج</h3><p>هذه الحقول تأتي من إصدار النموذج الخاص بنوع الطلب.</p></div>'+form.fields.filter(f=>f.visible).map(f=>wizardField(f)).join('')+'<span class="pill">إصدار النموذج '+form.version+'</span>'}
 if(wizardStep===4){const flow=wizard.flow||state.workflows[t];content='<div class="wizard-title"><h3>راجع الطلب قبل الإرسال</h3><p>لا يُنشأ حجز نهائي قبل اكتمال الاعتماد.</p></div><div class="wizard-summary">'+[['نوع الطلب',t],['الجهة',wizard.org],['المرافق',wizard.sites.map(siteName).join('، ')],['الفترة',fullTime(dubaiISO(wizard.start))+' ← '+fullTime(dubaiISO(wizard.end))],['المبرر',wizard.reason],['الإصدارات','النموذج '+form.version+' / التدفق '+flow.version]].map(([k,v])=>'<div class="key-value"><span>'+esc(k)+'</span><b style="max-width:70%">'+esc(v)+'</b></div>').join('')+'</div><h3 style="margin:15px 0 9px">جهات للعلم بعد الاعتماد</h3><div class="flex" style="flex-wrap:wrap">'+ORGS.map(o=>'<label class="check-label"><input type="checkbox" data-cc value="'+o+'" '+(wizard.cc.includes(o)?'checked':'')+'>'+o+'</label>').join('')+'</div><div class="note" style="margin-top:18px">مسار الطلب: '+flow.stages.map(s=>esc(s.name)).join(' ← ')+'</div>'}
 $('#requestDialogBody').innerHTML='<div class="dialog-head"><div><span class="eyebrow">NEW / ADMINISTRATIVE REQUEST</span><h2>'+(wizard.id?'تعديل وإعادة تقديم':'طلب إداري جديد')+'</h2><small>بيانات وتجربة افتراضية</small></div><button class="icon-button" onclick="closeRequest()" aria-label="إغلاق الطلب">'+icon('close')+'</button></div><div class="wizard-steps">'+['الجهة والنوع','المرافق والفترة','البيانات','المراجعة'].map((n,i)=>'<div class="wizard-step '+(wizardStep===i+1?'active':wizardStep>i+1?'done':'')+'"><i>'+(i+1)+'</i>'+n+'</div>').join('')+'</div><div class="dialog-content wizard-content">'+content+'<div class="error-text" id="wizardError" role="alert"></div></div><div class="dialog-actions"><button class="button" onclick="wizardNext(-1)" '+(wizardStep===1?'disabled':'')+'>السابق</button><button class="button ghost" onclick="submitWizard(true)">حفظ مسودة</button><span class="grow"></span><button class="button primary" onclick="wizardNext(1)">'+(wizardStep===4?'إرسال الطلب التجريبي':'التالي ←')+'</button></div>'}
function validateWizard(step){captureWizard();if(step>=1&&['تمديد','تعديل','إلغاء','إخلاء'].includes(wizard.type)&&!wizard.bookingRef)return 'اختر الحجز المعتمد المرتبط بالطلب.';if(step>=2){if(!wizard.sites.length)return 'اختر مرفقاً واحداً على الأقل.';if(!state.settings.multiSites&&wizard.sites.length>1)return 'الإعداد الحالي يسمح بمرفق واحد فقط.';if(!wizard.start||!wizard.end)return 'حدد بداية الفترة ونهايتها.';if(new Date(dubaiISO(wizard.end))<=new Date(dubaiISO(wizard.start)))return 'نهاية الفترة يجب أن تكون بعد بدايتها.';if(wizard.bookingRef){const b=state.bookings.find(b=>b.id===wizard.bookingRef);if(!b||b.status!=='confirmed')return 'الحجز المرتبط لم يعد نشطاً.';if(wizard.sites.length!==1||wizard.sites[0]!==b.site)return 'حدد المرفق نفسه الموجود في الحجز المرتبط.';if(wizard.type==='تمديد'&&new Date(dubaiISO(wizard.end))<=new Date(b.end))return 'التمديد يحتاج نهاية بعد نهاية الحجز الأصلي.'}}
 if(step>=3){for(const f of effectiveForm().fields.filter(f=>f.visible)){const v=wizard.values[f.id];if(f.required&&(!v||String(v).trim()===''))return 'الحقل «'+f.label+'» مطلوب.';if(f.kind==='number'&&v&&(!Number.isFinite(Number(v))||Number(v)<=0))return 'أدخل قيمة موجبة لحقل «'+f.label+'».'}if(effectiveForm().fields.some(f=>f.id==='reason'&&f.visible&&f.required)&&(wizard.reason||'').trim().length<10)return 'اكتب مبرراً لا يقل عن 10 أحرف.'}return ''}
function wizardNext(delta){if(delta<0){captureWizard();wizardStep=Math.max(1,wizardStep-1);renderWizard();return}const error=validateWizard(wizardStep);if(error){$('#wizardError').textContent=error;return}if(wizardStep===4){submitWizard(false);return}wizardStep++;renderWizard()}
function submitWizard(draft){captureWizard();if(!draft){const error=validateWizard(4);if(error){$('#wizardError').textContent=error;return}}let existing=wizard.id?state.requests.find(r=>r.id===wizard.id):null;const id=existing?.id||'MV-2026-'+String(186+state.requests.length).padStart(4,'0');let req={...clone(wizard),id,subject:wizard.subject||wizard.type+' — '+wizard.sites.map(siteName).join('، '),start:wizard.start?dubaiISO(wizard.start):dubaiISO('2026-11-02'),end:wizard.end?dubaiISO(wizard.end):null,status:draft?'draft':'submitted',flow:clone(wizard.flow||state.workflows[wizard.type]),form:clone(wizard.form||state.forms[wizard.type]),stage:0,done:[],revision:(existing?.revision||0)+1,createdAt:existing?.createdAt||new Date().toISOString(),createdRole:existing?.createdRole||'requester',history:existing?.history||[]};req.history.push({event:draft?'حفظ مسودة':existing?'إعادة تقديم':'تقديم الطلب',actor:ROLE_NAMES[state.role],at:new Date().toISOString()});if(existing)state.requests[state.requests.indexOf(existing)]=req;else state.requests.unshift(req);audit(draft?'حفظ مسودة':'تقديم طلب',id+' · '+req.type);selectedRequest=id;closeRequest();location.hash='requests';if(view==='requests')render();toast(draft?'حُفظت المسودة محلياً':'أُرسل الطلب للمراجعة التجريبية — لم ينشأ حجز نهائي')}
function showRequest(id){const r=visibleRequests().find(x=>x.id===id);if(!r)return toast('الطلب خارج النطاق المعروض');selectedRequest=id;if(can('review')){location.hash='review';if(view==='review')render();return}$('#detailDialogBody').innerHTML='<div class="dialog-head"><h2>تفاصيل الطلب</h2><button class="icon-button" onclick="closeDetail()" aria-label="إغلاق التفاصيل">'+icon('close')+'</button></div><div class="dialog-content">'+documentHTML(r,false)+'</div>';$('#detailDialog').showModal()}
function closeDetail(){$('#detailDialog').close()}
function timelineHTML(r){return '<div class="timeline">'+r.flow.stages.map((s,i)=>{const complete=i<r.stage||['approved','closed'].includes(r.status),active=i===r.stage&&r.status==='submitted';return '<div class="timeline-item '+(complete?'complete':active?'active':'')+'"><i>'+(complete?'✓':i+1)+'</i><div><b>'+esc(s.name)+'</b><br><small>'+((s.roles.length>1&&s.mode==='all')?'مراجعات متوازية — يلزم الجميع':s.mode==='any'?'تكفي موافقة واحدة':'مراجعة متسلسلة')+' · '+s.sla+' يوم</small><div class="task-chips">'+s.roles.map(role=>'<span class="task-chip '+(complete||(active&&r.done.includes(role))?'done':'')+'">'+ROLE_NAMES[role]+(complete||(active&&r.done.includes(role))?' ✓':'')+'</span>').join('')+'</div></div></div>'}).join('')+'</div>'}
function documentHTML(r,actions=true){const signed=r.signature;return '<div class="document-header"><div><span class="latin">'+esc(r.id)+'</span><h2>'+esc(r.type)+'</h2><p class="muted micro">'+(limited()?'جهة مقيدة':esc(r.org))+'</p></div><div class="stack" style="align-items:end;gap:8px">'+statusPill(r.status)+'<span class="micro muted">مراجعة '+r.revision+' · تدفق '+r.flow.version+' · نموذج '+r.form.version+'</span></div></div><div class="meta-grid"><div><dt>المرافق</dt><dd>'+r.sites.map(siteName).join('، ')+'</dd></div><div><dt>الفترة</dt><dd>'+fullTime(r.start)+'<br>'+fullTime(r.end)+'</dd></div><div><dt>الجهات المشاركة</dt><dd>'+esc((r.orgs||[r.org]).join('، '))+'</dd></div><div><dt>المرفقات</dt><dd>'+(limited()?'مقيدة':r.files?.length?r.files.map(f=>esc(f.name)).join('، '):'دون مرفقات')+'</dd></div></div><div class="reason">'+esc(r.reason||'مسودة غير مكتملة')+'</div>'+(r.lastNote?'<div class="note orange"><b>آخر ملاحظة:</b> '+esc(r.lastNote)+'</div>':'')+'<div class="document-grid"><section><h3>المراجعات المطلوبة</h3>'+timelineHTML(r)+'</section><section><h3>سجل الطلب</h3><div class="timeline">'+r.history.map(h=>'<div class="timeline-item complete"><i>✓</i><div><b>'+esc(h.event)+'</b><br><small>'+esc(h.actor)+' · '+fullTime(h.at)+'</small></div></div>').join('')+'</div></section></div>'+(signed?'<div class="document-signoff"><span class="eyebrow">DEMO APPROVAL / SIGNATURE</span><strong>'+esc(signed.name)+'</strong><small>'+esc(signed.role)+' · '+fullTime(signed.at)+'<br>توقيع تمثيلي داخل النموذج؛ لا توجد شهادة رقمية.</small></div>':'')+(['approved','closed'].includes(r.status)?'<div class="note">جهات للعلم: '+esc(r.cc?.join('، ')||'لم تحدد جهات')+'</div>':'')+(actions?reviewActions(r):'')}
function activeRoles(r){const st=r.flow.stages[r.stage];return st?.roles.filter(role=>!r.done.includes(role))||[]}
function canAct(r,role){return r.status==='submitted'&&(state.role==='admin'||state.role===role)&&can('review')&&(role!=='approver'||can('approve'))}
function reviewActions(r){if(r.status==='approved')return '<div class="review-actions"><button class="button primary" onclick="closeExecution(\''+r.id+'\')">تأكيد التنفيذ والإغلاق</button><span class="micro muted">ينهي الطلب الإداري؛ لا يغيّر نهاية الحجز تلقائياً.</span></div>';if(r.status!=='submitted')return '<div class="review-actions"><span class="micro muted">لا توجد مهمة مراجعة مفتوحة لهذا الطلب.</span>'+(r.status==='returned'&&can('create')?'<button class="button primary" onclick="editRequest(\''+r.id+'\')">تعديل وإعادة تقديم</button>':'')+'</div>';const roles=activeRoles(r);return '<div class="review-actions">'+roles.map(role=>'<button class="button primary" '+(!canAct(r,role)?'disabled':'')+' onclick="openDecision(\''+r.id+'\',\''+role+'\',\'approve\')">'+(role==='approver'?'اعتماد وتوقيع':'موافقة')+' — '+ROLE_NAMES[role]+'</button>').join('')+'<button class="button" '+(!roles.some(role=>canAct(r,role))?'disabled':'')+' onclick="openDecision(\''+r.id+'\',\''+roles.find(role=>canAct(r,role))+'\',\'return\')">إرجاع</button><button class="button danger" '+(!roles.some(role=>canAct(r,role))?'disabled':'')+' onclick="openDecision(\''+r.id+'\',\''+roles.find(role=>canAct(r,role))+'\',\'reject\')">رفض</button></div>'}
function renderReview(){const list=visibleRequests().filter(r=>r.status!=='draft');let r=list.find(r=>r.id===selectedRequest)||list[0];if(r){selectedRequest=r.id;selectedSite=r.sites[0];mapDate=localInput(r.start).slice(0,10)}return heading('REVIEW / DECISION DESK','مكتب المراجعة','البيانات، ومهام المراجعة، وسجل القرار، في مساحة واحدة.','<span class="pill orange">'+list.filter(r=>r.status==='submitted').length+' طلب قيد المراجعة</span>')+'<div class="review-layout"><aside class="card inbox"><h3>الطلبات الواردة</h3><div class="inbox-items">'+list.map(x=>'<button class="inbox-item '+(r?.id===x.id?'active':'')+'" onclick="selectedRequest=\''+x.id+'\';render()"><span class="latin">'+esc(x.id)+'</span><b>'+esc(x.type)+'</b><small>'+esc(x.org)+'</small><div style="margin-top:10px">'+statusPill(x.status)+'</div></button>').join('')+'</div><p class="micro muted" style="margin-top:12px">تغيير الدور من أعلى الشاشة يحاكي واجهة المراجع المختار.</p></aside><div class="stack">'+(r?'<article class="card request-document">'+documentHTML(r)+'</article>'+mapBox('document-map'):'<section class="card empty">لا توجد طلبات ضمن النطاق</section>')+'</div></div>'}
let decision=null;
function openDecision(id,role,action){const r=state.requests.find(x=>x.id===id);if(!r||!canAct(r,role))return toast('المهمة غير متاحة للدور المعروض');decision={id,role,action};const last=r.stage===r.flow.stages.length-1;const needsSignature=action==='approve'&&last&&state.settings.signatureRequired;$('#decisionDialogBody').innerHTML='<div class="dialog-head"><div><span class="eyebrow">DECISION / '+esc(id)+'</span><h2>'+(action==='return'?'إرجاع للتعديل':action==='reject'?'رفض الطلب':last?'اعتماد الطلب':'تسجيل الموافقة')+'</h2></div><button class="icon-button" onclick="closeDecision()" aria-label="إغلاق القرار">'+icon('close')+'</button></div><div class="dialog-content"><label class="field"><span>الملاحظة '+(action==='approve'?'— اختيارية':'— مطلوبة')+'</span><textarea id="decisionNote" placeholder="اكتب سبب القرار أو الملاحظة…"></textarea></label>'+(needsSignature?'<label class="field"><span>اسم المعتمد في التوقيع التمثيلي</span><input id="signatureName" value="معتمد تجريبي" autocomplete="off"></label><label class="check-label"><input type="checkbox" id="signatureAck">أؤكد الاعتماد داخل التجربة</label><div class="signature-preview"><span class="eyebrow">SIGNATURE / DEMO ONLY</span><span class="signature-name">توقيع تمثيلي</span><br><small>توثيق مرئي للتصور؛ لا يمثل توقيعاً بشهادة رقمية.</small></div>':'')+'<div id="decisionError" class="error-text" role="alert"></div></div><div class="dialog-actions"><button class="button primary" onclick="applyDecision()">تأكيد القرار التجريبي</button><button class="button" onclick="closeDecision()">إلغاء</button></div>' ;$('#decisionDialog').showModal()}
function closeDecision(){$('#decisionDialog').close()}
function bookingConflict(r){if(['إلغاء','إخلاء'].includes(r.type))return null;return state.bookings.find(b=>b.status==='confirmed'&&b.id!==r.bookingRef&&r.sites.includes(b.site)&&overlaps(r.start,r.end,b.start,b.end))}
function applyDecision(){const {id,role,action}=decision;const r=state.requests.find(x=>x.id===id);if(!r||!canAct(r,role))return toast('لم تعد المهمة متاحة');const note=$('#decisionNote').value.trim();if(action!=='approve'&&note.length<5){$('#decisionError').textContent='اكتب سبباً من 5 أحرف على الأقل.';return}const stage=r.flow.stages[r.stage];const last=r.stage===r.flow.stages.length-1;const completing=stage.mode==='any'||stage.roles.every(x=>x===role||r.done.includes(x));if(action==='approve'&&last&&completing){if(state.settings.signatureRequired&&(!$('#signatureName')?.value.trim()||!$('#signatureAck')?.checked)){$('#decisionError').textContent='أكمل اسم المعتمد وتأكيد الاعتماد.';return}const conflict=bookingConflict(r);if(conflict){$('#decisionError').textContent='تعذر تثبيت الحجز: '+siteName(conflict.site)+' محجوز خلال جزء من الفترة. يمكن إرجاع الطلب لتعديل الفترة.';return}}
 const at=new Date().toISOString();if(action==='return'||action==='reject'){r.status=action==='return'?'returned':'rejected';r.lastNote=note;r.history.push({event:action==='return'?'إرجاع للتعديل':'رفض الطلب',actor:ROLE_NAMES[role],at,note})}else {r.done.push(role);r.history.push({event:'موافقة — '+stage.name,actor:ROLE_NAMES[role],at,note});if(note)r.lastNote=note;if(completing){r.stage++;r.done=[];if(last){r.status='approved';r.signature={name:$('#signatureName')?.value.trim()||'معتمد تجريبي',role:ROLE_NAMES[role],at,mode:'demonstration'};if(r.bookingRef){const b=state.bookings.find(b=>b.id===r.bookingRef);if(['إلغاء','إخلاء'].includes(r.type)){b.status=r.type==='إلغاء'?'cancelled':'released';b.closedBy=r.id}else{b.previous={start:b.start,end:b.end};b.start=r.start;b.end=r.end;b.updatedBy=r.id}}else r.sites.forEach(site=>state.bookings.push({id:'BK-'+Date.now()+'-'+site,site,org:r.org,start:r.start,end:r.end,status:'confirmed',requestId:r.id}));r.history.push({event:'تثبيت القرار والحجز الإداري',actor:ROLE_NAMES[role],at})}}}
 audit(action==='approve'?'موافقة على طلب':action==='return'?'إرجاع طلب':'رفض طلب',id+' · '+ROLE_NAMES[role]);closeDecision();render();toast(r.status==='approved'?'اكتمل الاعتماد وسُجل الحجز التجريبي':action==='return'?'أعيد الطلب مع الملاحظة':action==='reject'?'سُجل الرفض':'سُجلت الموافقة وانتقل مسار المراجعة')}
function closeExecution(id){const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='approved'||!can('review'))return;r.status='closed';r.history.push({event:'تأكيد التنفيذ وإغلاق الطلب',actor:ROLE_NAMES[state.role],at:new Date().toISOString()});audit('إغلاق طلب',id);render();toast('أُغلق الطلب؛ الحجز يحتفظ بفترته المعتمدة')}
function setCalendarDay(day){calendarDay=day;mapDate='2026-11-'+String(day+1).padStart(2,'0');render()}
function renderCalendar(){mapDate='2026-11-'+String(calendarDay+1).padStart(2,'0');const list=visibleSites();const selected=list.find(s=>s.id===selectedSite)||list[0];if(selected)selectedSite=selected.id;const b=state.bookings.filter(b=>b.status==='confirmed'&&b.site===selectedSite);let cells='<div class="day-head row-name">المرفق / نوفمبر</div>'+Array.from({length:7},(_,i)=>'<div class="day-head">'+String(i+1).padStart(2,'0')+' نوفمبر</div>').join('');cells+=list.map(s=>'<div class="row-name"><button onclick="selectedSite=\''+s.id+'\';render()">'+s.name+'</button></div>'+Array.from({length:7},(_,i)=>{const a=availability(s.id,'2026-11-'+String(i+1).padStart(2,'0'));return '<div role="button" tabindex="0" class="time-cell '+(calendarDay===i&&selectedSite===s.id?'active':'')+'" aria-label="'+s.name+' '+(i+1)+' نوفمبر '+a.label+'" onclick="selectedSite=\''+s.id+'\';setCalendarDay('+i+')" onkeydown="if(event.key===\'Enter\'){selectedSite=\''+s.id+'\';setCalendarDay('+i+')} "><span class="booking-line '+(a.key==='pending'?'pending':a.key==='free'?'free':'')+'"></span></div>'}).join('')).join('');return heading('CALENDAR / SPACE OVER TIME','الإشغال عبر الزمن','حالة المرفق تتبع الفترة؛ سجل الموقع يحتفظ بهويته.','<span class="pill">01 — 07 نوفمبر 2026</span>')+'<div class="calendar-layout"><div class="stack">'+mapBox('calendar-map')+'<section class="card"><div class="column-heading flex spread"><h3>جدول إشغال المرافق</h3><span class="micro muted">اختر خلية لتغيير الموقع واليوم</span></div><div class="table-scroll"><div class="calendar-grid">'+cells+'</div></div></section></div><aside class="card calendar-side"><span class="eyebrow">DAY / '+String(calendarDay+1).padStart(2,'0')+'</span><h2>'+fullDate(dubaiISO(mapDate))+'</h2><div class="calendar-daylist">'+Array.from({length:7},(_,i)=>'<button class="'+(calendarDay===i?'active':'')+'" onclick="setCalendarDay('+i+')">'+String(i+1).padStart(2,'0')+'</button>').join('')+'</div><div class="rule"></div><h3>'+siteName(selectedSite)+'</h3><p class="muted micro" style="margin:7px 0 15px">الحجوزات المعتمدة لهذا المرفق</p>'+b.map(x=>'<div class="calendar-booking"><b>'+(limited()?'حجز معتمد':esc(x.org))+'</b><small>'+fullDate(x.start)+' ← '+fullDate(x.end)+'</small><br><span class="pill green">معتمد</span></div>').join('')+(!b.length?'<p class="micro muted">لا توجد حجوزات معتمدة في بيانات العرض.</p>':'')+'<div class="note" style="margin-top:18px">الطلب البرتقالي لا يحجز المرفق حصرياً قبل الاعتماد.</div></aside></div>'}
function renderOrg(){const list=SITES.filter(s=>(orgSelected==='all'||s.org===orgSelected)&&scopeAllows(s.org,s.id));return heading('ORGANIZATION / MEMBERSHIP & SCOPE','الهيكل التنظيمي','الجهة والموقع سجّلان مستقلان، ويرتبطان بالحجوزات والطلبات.','<span class="pill">4 جهات تجريبية</span>')+'<div class="org-layout"><aside class="card org-tree"><h3>شجرة الجهات</h3><div class="org-nodes"><button class="org-node '+(orgSelected==='all'?'active':'')+'" onclick="orgSelected=\'all\';render()">'+icon('tree')+'المؤسسة<small>04</small></button>'+ORGS.map((o,i)=>'<button class="org-node child '+(orgSelected===o?'active':'')+'" onclick="orgSelected=\''+o+'\';render()">'+icon('building')+o+'<small>'+SITES.filter(s=>s.org===o).length+'</small></button>').join('')+'</div></aside><div class="stack"><section class="card org-summary"><span class="eyebrow">ORGANIZATION / PROFILE</span><h2>'+(orgSelected==='all'?'المؤسسة':orgSelected)+'</h2><p class="micro muted" style="margin-top:7px">ارتباطات إدارية افتراضية بالمرافق.</p><div class="org-members">'+[['مستخدم تجريبي أ','مدير الجهة'],['مستخدم تجريبي ب','منسق المرافق'],['مستخدم تجريبي ج','مراجع إداري'],['مستخدم تجريبي د','مقدم طلب']].map(([n,r],i)=>'<div class="member"><span class="avatar">'+String(i+1).padStart(2,'0')+'</span><span><b>'+n+'</b><small>'+r+'</small></span></div>').join('')+'</div></section><section class="card"><div class="column-heading"><h3>المرافق المرتبطة</h3></div><div class="table-scroll"><table class="data-table"><thead><tr><th>المرفق</th><th>التصنيف</th><th>السعة</th><th>إجراء</th></tr></thead><tbody>'+list.map(s=>'<tr><td>'+s.name+'</td><td>'+s.kind+'</td><td>'+s.capacity+'</td><td><button class="button compact" onclick="selectedSite=\''+s.id+'\';orgFilter=\'all\';location.hash=\'map\'">على الخريطة</button></td></tr>').join('')+'</tbody></table></div></section><div class="note">تغيير تبعية الشخص يعيد تحديد نطاقه. تبقى الطلبات مرتبطة بالجهة، وتُحفظ هوية المعتمد وقت القرار. هذه سياسة مقترحة للبناء.</div></div></div>'}
function loadFlowDraft(type){flowType=type;flowDraft=clone(state.workflows[type]);render()}
function setStage(i,key,value){if(key==='sla')value=Math.max(1,Number(value)||1);flowDraft.stages[i][key]=value}
function toggleStageRole(i,role,on){let a=flowDraft.stages[i].roles;flowDraft.stages[i].roles=on?[...new Set([...a,role])]:a.filter(x=>x!==role)}
function moveStage(i,delta){const j=i+delta;if(j<0||j>=flowDraft.stages.length)return;[flowDraft.stages[i],flowDraft.stages[j]]=[flowDraft.stages[j],flowDraft.stages[i]];render()}
function dropStage(i,e){e.preventDefault();const from=draggedStage;if(from===null||from===i)return;const [s]=flowDraft.stages.splice(from,1);flowDraft.stages.splice(i,0,s);draggedStage=null;render()}
function addStage(){flowDraft.stages.splice(Math.max(0,flowDraft.stages.length-1),0,{id:'st'+Date.now(),name:'مراجعة إضافية',roles:['facilities'],mode:'all',sla:2});render()}
function removeStage(i){if(flowDraft.stages.length<=1)return toast('يجب أن يبقى مسار اعتماد واحد على الأقل');flowDraft.stages.splice(i,1);render()}
function publishFlow(){if(!can('configure'))return;const last=flowDraft.stages.at(-1);if(!flowDraft.stages.length||flowDraft.stages.some(s=>!s.name.trim()||!s.roles.length))return toast('أكمل أسماء المراحل والمراجعين');if(last.roles.length!==1||last.roles[0]!=='approver')return toast('المرحلة الأخيرة يجب أن تتضمن صاحب الاعتماد فقط في هذا التصور');flowDraft.version=state.workflows[flowType].version+1;state.workflows[flowType]=clone(flowDraft);audit('نشر إصدار تدفق',flowType+' · v'+flowDraft.version);render();toast('نُشر الإصدار '+flowDraft.version+' للطلبات الجديدة؛ الطلبات السابقة تحتفظ بإصدارها')}
function renderWorkflow(){if(!flowDraft)flowDraft=clone(state.workflows[flowType]);const f=flowDraft;return heading('STUDIO / WORKFLOW DESIGNER','استوديو التدفقات','رتّب المراحل، وحدد المراجعين، ثم انشر إصداراً جديداً.','<button class="button" onclick="loadFlowDraft(flowType)">إلغاء التغييرات</button><button class="button primary" onclick="publishFlow()">نشر إصدار جديد</button>')+'<div class="studio-layout"><section class="card studio-canvas"><div class="studio-flow"><span class="flow-cap">تقديم الطلب</span><span class="flow-connector"></span>'+f.stages.map((s,i)=>'<article class="flow-node" draggable="true" ondragstart="draggedStage='+i+'" ondragover="event.preventDefault()" ondrop="dropStage('+i+',event)"><div class="flex"><i class="node-order">'+(i+1)+'</i><input aria-label="اسم المرحلة '+(i+1)+'" value="'+esc(s.name)+'" onchange="setStage('+i+',\'name\',this.value)"><div class="node-tools"><button onclick="moveStage('+i+',-1)" aria-label="رفع المرحلة '+(i+1)+'">↑</button><button onclick="moveStage('+i+',1)" aria-label="خفض المرحلة '+(i+1)+'">↓</button><button onclick="removeStage('+i+')" aria-label="حذف المرحلة '+(i+1)+'">×</button></div></div><div class="stage-options">'+['facilities','manager','approver'].map(role=>'<label class="role-choice"><input type="checkbox" '+(s.roles.includes(role)?'checked':'')+' onchange="toggleStageRole('+i+',\''+role+'\',this.checked)">'+ROLE_NAMES[role]+'</label>').join('')+'</div><div class="stage-options"><span>إتمام المرحلة</span><select onchange="setStage('+i+',\'mode\',this.value)"><option value="all" '+(s.mode==='all'?'selected':'')+'>موافقة الجميع</option><option value="any" '+(s.mode==='any'?'selected':'')+'>موافقة أحدهم</option></select><span>المهلة</span><input aria-label="مهلة المرحلة '+(i+1)+'" type="number" min="1" value="'+s.sla+'" style="width:45px;border-color:var(--line)" onchange="setStage('+i+',\'sla\',this.value)"><span>يوم</span></div></article><span class="flow-connector"></span>').join('')+'<span class="flow-cap">تثبيت القرار والحجز</span></div><div style="text-align:center;margin-top:25px"><button class="button" onclick="addStage()">＋ إضافة مراجعة</button></div></section><aside class="card studio-side"><div class="version-card"><b>v'+state.workflows[flowType].version+'</b><span><strong>الإصدار المنشور</strong><small>الطلبات الجديدة تستخدم هذا الإصدار</small></span></div><label class="field"><span>نوع الطلب المرتبط</span><select onchange="loadFlowDraft(this.value)">'+TYPES.map(t=>'<option '+(t===flowType?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="field"><span>اسم التدفق</span><input value="'+esc(f.name)+'" onchange="flowDraft.name=this.value"></label><div class="rule"></div><h3>كيف تعمل المراجعات؟</h3><p class="publish-info" style="margin-top:10px">المراحل تُنفذ بالتسلسل. إذا احتوت مرحلة على أكثر من مراجع تُفتح لهم مهام متوازية، ويحدد اختيار «الجميع» أو «أحدهم» شرط انتقالها.</p><div class="note" style="margin-top:18px">السحب يعيد ترتيب المراحل. تتوفر الأسهم للاستخدام باللمس ولوحة المفاتيح.</div><p class="publish-info" style="margin-top:14px">النموذج يعرض ترتيباً ومجموعات مراجعة. محرر BPMN والتفرعات الشرطية الكاملة موصوفان في حزمة البناء.</p></aside></div>'}
function loadFormDraft(type){formType=type;formDraft=clone(state.forms[type]);render()}
function setField(i,key,value){formDraft.fields[i][key]=value;if(['visible','required','kind'].includes(key))renderFormPreview()}
function addField(){const name=$('#newFieldName').value.trim();if(!name)return toast('اكتب اسم الحقل');const kind=$('#newFieldKind').value;formDraft.fields.push({id:'field_'+Date.now(),label:name,kind,required:false,visible:true,options:kind==='select'?'خيار أ,خيار ب':''});render()}
function removeField(i){if(formDraft.fields[i].id==='reason')return toast('المبرر حقل أساسي في هذا التصور');formDraft.fields.splice(i,1);render()}
function publishForm(){if(formDraft.fields.some(f=>!f.label.trim()))return toast('أكمل أسماء الحقول');if(new Set(formDraft.fields.map(f=>f.id)).size!==formDraft.fields.length)return toast('توجد معرفات حقول مكررة');formDraft.version=state.forms[formType].version+1;state.forms[formType]=clone(formDraft);audit('نشر إصدار نموذج',formType+' · v'+formDraft.version);render();toast('نُشر النموذج للطلبات الجديدة')}
function renderFormPreview(){const el=$('#fieldPreview');if(!el)return;const old=wizard;wizard={values:{},files:[]};el.innerHTML='<span class="preview-stamp">FORM / LIVE PREVIEW</span><h3>'+esc(formType)+'</h3>'+formDraft.fields.filter(f=>f.visible).map(f=>wizardField(f,true)).join('');wizard=old}
function renderForms(){if(!formDraft)formDraft=clone(state.forms[formType]);return heading('STUDIO / FORM BUILDER','استوديو النماذج','خصص الحقول والإلزامية، ثم انشر نسخة تُستخدم في الطلبات الجديدة.','<button class="button" onclick="loadFormDraft(formType)">إلغاء التغييرات</button><button class="button primary" onclick="publishForm()">نشر النموذج</button>')+'<div class="card filterbar"><label>نوع الطلب<select onchange="loadFormDraft(this.value)">'+TYPES.map(t=>'<option '+(t===formType?'selected':'')+'>'+t+'</option>').join('')+'</select></label><span class="pill green">الإصدار المنشور '+state.forms[formType].version+'</span><span class="micro muted">معرفات الحقول ثابتة بين الإصدارات</span></div><div class="forms-layout"><section class="card"><div class="table-scroll"><table class="data-table field-table"><thead><tr><th>الحقل</th><th>النوع</th><th>ظاهر</th><th>مطلوب</th><th>إجراء</th></tr></thead><tbody>'+formDraft.fields.map((f,i)=>'<tr><td><input type="text" aria-label="اسم الحقل '+(i+1)+'" value="'+esc(f.label)+'" onchange="setField('+i+',\'label\',this.value);renderFormPreview()"><br><span class="latin tiny muted">'+f.id+'</span></td><td><select aria-label="نوع الحقل '+(i+1)+'" onchange="setField('+i+',\'kind\',this.value)">'+[['text','نص'],['textarea','نص طويل'],['number','رقم'],['date','تاريخ'],['select','قائمة'],['files','مرفقات']].map(([id,n])=>'<option value="'+id+'" '+(id===f.kind?'selected':'')+'>'+n+'</option>').join('')+'</select></td><td><input type="checkbox" aria-label="إظهار الحقل '+(i+1)+'" '+(f.visible?'checked':'')+' onchange="setField('+i+',\'visible\',this.checked)"></td><td><input type="checkbox" aria-label="إلزام الحقل '+(i+1)+'" '+(f.required?'checked':'')+' onchange="setField('+i+',\'required\',this.checked)"></td><td><button class="icon-button" onclick="removeField('+i+')" aria-label="حذف الحقل '+(i+1)+'">×</button></td></tr>').join('')+'</tbody></table></div><div class="field-add"><input id="newFieldName" placeholder="اسم حقل جديد…" aria-label="اسم الحقل الجديد"><select id="newFieldKind" aria-label="نوع الحقل الجديد"><option value="text">نص</option><option value="textarea">نص طويل</option><option value="number">رقم</option><option value="date">تاريخ</option><option value="select">قائمة</option></select><button class="button primary compact" onclick="addField()">＋ إضافة</button></div><div class="legend-note">أسماء الحقول وتغييراتها تجريبية. قواعد التعبئة والتكامل المتقدمة موصوفة ضمن حزمة البناء.</div></section><aside id="fieldPreview" class="card field-preview"></aside></div>'}
function updatePermission(role,key,value){if(role==='admin')return;state.permissions[role][key]=value;audit('تعديل صلاحية تجريبية',ROLE_NAMES[role]+' / '+PERMISSION_NAMES[key]+': '+value);navigation();toast('حُفظ إعداد الصلاحية التجريبي')}
function renderPermissions(){return heading('ACCESS / ROLE & RESOURCE SCOPE','مركز الصلاحيات','الإجراء المسموح ونطاق البيانات يُحددان بصورة مستقلة.','<span class="pill">معاينة واجهة؛ التنفيذ الفعلي في الخادم</span>')+'<section class="card"><div class="column-heading"><h3>مصفوفة الأدوار والإجراءات</h3></div><div class="table-scroll"><table class="data-table matrix-table"><thead><tr><th>الدور</th>'+PERMISSIONS.map(p=>'<th>'+PERMISSION_NAMES[p]+'</th>').join('')+'<th>نطاق البيانات</th></tr></thead><tbody>'+Object.keys(ROLE_NAMES).map(role=>'<tr><td>'+ROLE_NAMES[role]+'</td>'+PERMISSIONS.map(p=>'<td><input type="checkbox" aria-label="'+ROLE_NAMES[role]+' '+PERMISSION_NAMES[p]+'" '+(state.permissions[role][p]?'checked':'')+' '+(role==='admin'?'disabled':'')+' onchange="updatePermission(\''+role+'\',\''+p+'\',this.checked)"></td>').join('')+'<td><select aria-label="نطاق '+ROLE_NAMES[role]+'" '+(role==='admin'?'disabled':'')+' onchange="state.scopes[\''+role+'\']=this.value;audit(\'تعديل نطاق تجريبي\',\''+ROLE_NAMES[role]+'\')">'+[['all','جميع البيانات'],['organization','حسب الجهة'],['site','حسب الموقع'],['both','الجهة والموقع']].map(([id,n])=>'<option value="'+id+'" '+(state.scopes[role]===id?'selected':'')+'>'+n+'</option>').join('')+'</select></td></tr>').join('')+'</tbody></table></div><div class="legend-note">نطاق العرض التجريبي للجهة: الخدمات المشتركة. نطاق المواقع: المرافق 02 و05 و08.</div></section><div class="settings-grid" style="margin-top:18px"><section class="card padding"><h3>معاينة البيانات المختصرة</h3><p class="micro muted" style="margin:10px 0 15px">دور «اطلاع محدود» يعرض المرافق دون الجهة الشاغلة أو المرفقات.</p><button class="button" onclick="changeRole(\'limited\');location.hash=\'map\'">تجربة الاطلاع المحدود</button></section><section class="card padding"><h3>سياسة تغيير التبعية</h3><ul class="test-list"><li>'+icon('check')+'عضوية الشخص مؤرخة وقابلة للانتهاء.</li><li>'+icon('check')+'المهام تتبع الدور الإداري حيثما أمكن.</li><li>'+icon('check')+'التوقيعات السابقة تحتفظ بصفة المعتمد وقت القرار.</li></ul><p class="micro muted">هذه سياسات مطلوبة في البناء؛ ليس هذا النموذج نظام دخول أو تفويض فعلياً.</p></section></div>'}
function setSetting(key,value){state.settings[key]=value;audit('تعديل إعداد',key+' = '+value);toast('حُفظ الإعداد؛ يطبق على الطلبات التالية')}
function renderSettings(){return heading('CONFIGURATION / SYSTEM POLICIES','إعدادات النظام','قرارات قابلة للتهيئة، مع سجل لتغييرات الإعدادات.','<button class="button" onclick="exportState()">'+icon('download')+'تصدير بيانات التجربة</button>')+'<div class="settings-grid"><section class="card padding"><h2>سياسات الطلب</h2>'+[['multiSites','عدة مرافق في الطلب','السماح باختيار أكثر من مرفق'],['multiOrgs','جهات مشاركة متعددة','إظهار اختيار الجهات المشاركة'],['signatureRequired','تأكيد الاعتماد والتوقيع','إلزام تأكيد مرئي في المحاكاة']].map(([key,title,desc])=>'<label class="setting-row"><span><b>'+title+'</b><small>'+desc+'</small></span><input class="toggle" type="checkbox" '+(state.settings[key]?'checked':'')+' onchange="setSetting(\''+key+'\',this.checked)" aria-label="'+title+'"></label>').join('')+'<label class="setting-row"><span><b>وحدة الفترة الافتراضية</b><small>يمكن تغييرها أثناء الطلب</small></span><select onchange="setSetting(\'defaultUnit\',this.value)"><option value="days" '+(state.settings.defaultUnit==='days'?'selected':'')+'>أيام</option><option value="hours" '+(state.settings.defaultUnit==='hours'?'selected':'')+'>ساعات</option></select></label></section><section class="card padding"><h2>البيئة المستهدفة</h2>'+[['النشر','Docker داخل شبكة معزولة'],['اللغة والاتجاه','عربي / RTL'],['المنطقة الزمنية','Asia/Dubai'],['هدف حجم السجلات','7,000 جهة / 200,000 شخص'],['مصدر الخريطة في العرض','نسخة إقليمية مفتوحة مضمّنة'],['التوقيع الحالي','تمثيلي — دون شهادة رقمية']].map(([k,v])=>'<div class="key-value"><span>'+k+'</span><b>'+v+'</b></div>').join('')+'<p class="micro muted" style="margin-top:13px">الأعداد أهداف للمواصفات، وليست سجلات محملة أو نتيجة اختبار أداء.</p></section><section class="card padding"><h2>التكاملات المطلوبة لاحقاً</h2>'+[['الدخول المؤسسي','موصل هوية داخلي'],['الهيكل والأشخاص','مصدر مرجعي قابل للمزامنة'],['المراسلات','موصل بعد تحديد النظام'],['التوقيع الرقمي','يتطلب تحديد المزود والشهادات']].map(([k,v])=>'<div class="key-value"><span>'+k+'</span><b>'+v+'</b></div>').join('')+'</section><section class="card padding"><h2>إعادة التجربة</h2><p class="micro muted" style="margin:12px 0 18px">يعيد بيانات العرض الافتراضية في هذا المتصفح فقط. يمكنك تصديرها أولاً.</p><button class="button danger" onclick="openReset()">إعادة بيانات النموذج</button><div class="note" style="margin-top:18px">حزمة البناء تحدد النسخ الاحتياطي، والاستعادة، وإصدارات النماذج، وتحديث الخرائط محلياً.</div></section></div>'}
function exportState(){download('mover-prototype-data.json',JSON.stringify({exportedAt:new Date().toISOString(),scope:'fictional-administrative-prototype',...state},null,2));toast('تم تصدير بيانات التجربة المحلية')}
function openReset(){$('#decisionDialogBody').innerHTML='<div class="dialog-head"><h2>إعادة بيانات النموذج؟</h2><button class="icon-button" onclick="closeDecision()" aria-label="إغلاق">×</button></div><div class="dialog-content"><p class="micro muted">ستعاد بيانات العرض المحلية والإعدادات إلى البداية. صدّر نسخة إذا أردت الاحتفاظ بتجربتك.</p></div><div class="dialog-actions"><button class="button danger" onclick="resetState()">إعادة البيانات التجريبية</button><button class="button" onclick="closeDecision()">إلغاء</button></div>';$('#decisionDialog').showModal()}
function resetState(){state=defaults();persist();flowDraft=null;formDraft=null;closeDecision();location.hash='map';if(view==='map')render();toast('أعيدت بيانات العرض الافتراضية')}
function renderAudit(){return heading('AUDIT / ADMINISTRATIVE RECORD','سجل الإجراءات','تغييرات الطلبات والموافقات والإعدادات داخل التجربة.','<button class="button" onclick="download(\'mover-demo-audit.json\',JSON.stringify(state.audit,null,2))">'+icon('download')+'تصدير السجل</button>')+'<section class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>الوقت</th><th>الإجراء</th><th>الدور</th><th>التفصيل</th></tr></thead><tbody>'+state.audit.map(a=>'<tr><td>'+fullTime(a.at)+'</td><td>'+esc(a.event)+'</td><td>'+esc(a.actor)+'</td><td style="white-space:normal;max-width:400px">'+esc(a.detail)+'</td></tr>').join('')+'</tbody></table></div><div class="legend-note">هذا سجل محلي قابل لإعادة الضبط؛ سجل التدقيق الإنتاجي موصوف في حزمة البناء.</div></section>'}
function renderHandoff(){const files=[['START_HERE.md','ابدأ من هنا','ترتيب قراءة الملفات وكيفية تسليم الحزمة إلى Claude.'],['CLAUDE_BUILD_PROMPT.md','تعليمات البناء لـClaude','نطاق واضح وخطة تنفيذ ومخرجات مطلوب تسليمها.'],['REQUIREMENTS.md','المتطلبات الوظيفية','متطلبات مرقمة وشاشات وقواعد أعمال.'],['ARCHITECTURE.md','المعمارية والنشر','المكونات والبيئة المعزولة وحدود المسؤوليات.'],['DATA_MODEL.md','نموذج البيانات','الموقع والحجز والطلب والقرار والإصدارات.'],['API_CONTRACT.md','عقد الواجهات','إجراءات الخادم والأخطاء والتزامن والصلاحيات.'],['ACCEPTANCE_TESTS.md','اختبارات القبول','رحلات التحقق والحجز المتعارض والتفويض والإصدارات.'],['DECISIONS.md','القرارات والافتراضات','ما اعتمده المستخدم وما يزال بحاجة إلى تحديد.'],['SOURCES.md','المراجع والتراخيص','مصادر رسمية وملاحظات مكتبات الطرف الثالث.']];return heading('HANDOFF / BUILD PACKAGE','حزمة البناء إلى Claude','تصور قابل للتجربة، ومواصفات قابلة للتحويل إلى برنامج فعلي.')+'<section class="handoff-hero"><div><span class="eyebrow">MOVER / ADMINISTRATIVE FACILITIES</span><h2>من تجربة واضحة، إلى بناء قابل للتحقق.</h2><p>هذه الحزمة تخص إدارة المرافق والحجوزات والموافقات الإدارية. تحتوي على النموذج الحالي والمتطلبات ونموذج البيانات وخطة التنفيذ واختبارات القبول. البرنامج الإنتاجي سيُبنى في مرحلة منفصلة.</p></div><aside><a class="button primary full" href="mover-claude-handoff.zip" download>'+icon('download')+'تنزيل حزمة Claude</a><a class="button ghost full" style="margin-top:10px" href="handoff/CLAUDE_BUILD_PROMPT.md" download>تنزيل تعليمات البناء</a></aside></section><div class="handoff-files">'+files.map(([name,title,desc])=>'<article class="card file-card"><span class="file-icon">'+icon('file')+'</span><h3>'+title+'</h3><p>'+desc+'</p><a href="handoff/'+name+'" download><span class="latin">'+name+'</span> ↓</a></article>').join('')+'</div><div class="roadmap">'+[['01','تثبيت الأساس','المشروع والهوية والهيكل وقواعد البيانات.'],['02','رحلة مكتملة','طلب ومراجعة واعتماد وحجز ومنع تعارض.'],['03','التهيئة والتوسع','النماذج والتدفقات والصلاحيات والتفويض.'],['04','الجاهزية للتشغيل','العزل والنسخ والاستعادة والأداء والتوثيق.']].map(([n,t,d])=>'<article class="card"><b>'+n+'</b><h3>'+t+'</h3><p>'+d+'</p></article>').join('')+'</div><div class="note orange">ما يحتاج حسمًا لاحقاً: نوع التوقيع، ومصدر الدخول المؤسسي، ونظام الإحداثيات الفني، وعدد المستخدمين المتزامنين، وأهداف الاستعادة. لا ينبغي اختراع هذه القرارات أثناء البناء.</div>'}
window.addEventListener('hashchange',route);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('nav-open');$('#navShade').hidden=true}});
